const ORACLE_CASE_COUNT: usize = 1886;

use serde_json::Value;
use ukiryu::shell::posix::{Bash, Dash, Sh, Zsh};
use ukiryu::shell::{base, ShellFormatting};

fn text(value: &Value) -> &str {
    value.as_str().expect("oracle string")
}

fn executable(shell: &str) -> &'static str {
    match shell {
        "bash" => Bash::EXECUTABLE,
        "zsh" => Zsh::EXECUTABLE,
        "sh" => Sh::EXECUTABLE,
        "dash" => Dash::EXECUTABLE,
        other => panic!("no executable constant for {other}"),
    }
}

fn shell(name: &str) -> &'static dyn ShellFormatting {
    match name {
        "bash" => &Bash,
        "zsh" => &Zsh,
        "sh" => &Sh,
        "dash" => &Dash,
        other => panic!("unknown oracle shell {other}"),
    }
}

fn actual(case: &Value) -> Value {
    let input = &case["input"];
    let op = text(&case["op"]);
    let name = text(&case["shell"]);
    if name == "base" {
        let value = text(&input["value"]);
        return match op {
            "needs_quoting" => Value::Bool(base::needs_quoting(value)),
            "format_path" => Value::String(base::format_path(value)),
            other => panic!("unknown base op {other}"),
        };
    }
    let target = shell(name);
    match op {
        "name" => Value::String(target.name().to_owned()),
        "executable" | "shell_command" => Value::String(executable(name).to_owned()),
        "escape" => Value::String(target.escape(text(&input["value"]))),
        "quote" => Value::String(target.quote(text(&input["value"]))),
        "needs_quoting" => Value::Bool(target.needs_quoting(text(&input["value"]))),
        "format_path" => Value::String(target.format_path(text(&input["value"]))),
        "env_var" => Value::String(target.env_var(text(&input["value"]))),
        "join" => {
            let arguments: Vec<String> = input["args"]
                .as_array()
                .expect("oracle args")
                .iter()
                .map(|argument| text(argument).to_owned())
                .collect();
            Value::String(target.join(text(&input["executable"]), &arguments))
        }
        other => panic!("unknown oracle op {other}"),
    }
}

#[test]
fn oracle_cases_match_byte_for_byte() {
    let document: Value = serde_json::from_str(ORACLE_JSON).expect("oracle JSON");
    let cases = document["cases"].as_array().expect("oracle cases");
    assert_eq!(cases.len(), ORACLE_CASE_COUNT, "oracle case count drifted");
    let mut failures = Vec::new();
    for case in cases {
        let expected = case.get("ok").unwrap_or_else(|| {
            panic!("oracle raised for {case}; no Rust error contract exists for this op")
        });
        let got = actual(case);
        if &got != expected {
            failures.push(format!(
                "{} {} {}: expected {expected}, got {got}",
                case["shell"], case["op"], case["input"]
            ));
        }
    }
    assert!(
        failures.is_empty(),
        "{} of {} oracle cases differ:\n{}",
        failures.len(),
        cases.len(),
        failures.join("\n")
    );
}
